#define  SIZE_IN_NEXT_LONG            7

/* Language Encoding Constants */
#define LANG_ID_CODE_ENGLISH            ((UINT16) 0x656e)   /* "en" */
#define LANG_ID_CHAR_ENCODE_UTF8        ((UINT16) 0x006a)   /* UTF-8 */

